const req = $input.first().json;
const CHANNELS = { email: 90, sms: 30, telegram: 60 };

function parseJson(raw, fallback) {
  if (raw && typeof raw === "object") { return raw; }
  if (typeof raw === "string" && raw.trim()) {
    try { return JSON.parse(raw); } catch (e) { return fallback; }
  }
  return fallback;
}
function fnv(s) {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); }
  return (h >>> 0).toString(16).padStart(8, "0");
}

const lead = parseJson(req.lead, {});
const qual = parseJson(req.qualification, {});
const channel = String(req.channel || "email").trim().toLowerCase();
const maxWords = CHANNELS[channel] === undefined ? 90 : CHANNELS[channel];
const dryRun = String(req.dry_run === undefined || req.dry_run === null || req.dry_run === "" ? "true" : req.dry_run).toLowerCase() !== "false";

const rawTenant = String(req.tenant_id || qual.tenant_id || "default").trim().toLowerCase();
const tenantId = /^[a-z0-9][a-z0-9_-]{0,62}$/.test(rawTenant) ? rawTenant : "";
const traceId = String(req.trace_id || qual.trace_id || "").trim().slice(0, 64);

const leadKey = String(qual.lead_key || lead.email || "").trim().toLowerCase();
const tier = String(qual.tier || "UNKNOWN");
const score = Number(qual.score === undefined ? 0 : qual.score);

const leadLines = [];
["first_name", "last_name", "job_title", "company_name", "message", "use_case"].forEach(function (f) {
  if (lead[f] !== undefined && lead[f] !== null && String(lead[f]).trim()) { leadLines.push(f + ": " + String(lead[f]).trim()); }
});
if (lead.email) { leadLines.push("email: " + String(lead.email).trim()); }
const leadBlock = leadLines.join("\n");

const evidence = Array.isArray((qual.signals || {}).evidence) ? qual.signals.evidence : [];
const evidenceLines = evidence.map(function (e) { return "- " + String((e && e.signal) || "signal") + ": \"" + String((e && e.quote) || "") + "\""; });
const evidenceBlock = evidenceLines.length ? evidenceLines.join("\n") : "(no quoted evidence was collected during qualification)";

const groundTruth = (leadBlock + "\n" + evidenceLines.join("\n")).toLowerCase();

const blockers = [];
if (!tenantId) { blockers.push("tenant_id must match ^[a-z0-9][a-z0-9_-]{0,62}$; got " + JSON.stringify(rawTenant)); }
if (!leadKey) { blockers.push("the request carries no lead key or email, so there is nobody to write to"); }
if (qual.outreach_allowed !== true) { blockers.push("qualification did not allow outreach: " + (qual.outreach_block_reason || "no reason given")); }
if (CHANNELS[channel] === undefined) { blockers.push("channel \"" + channel + "\" is not one of email, sms, telegram"); }
if (channel === "telegram" && !String(req.chat_id || "").trim()) { blockers.push("the telegram channel needs a chat_id"); }

return [{ json: {
  lead: lead,
  lead_key: leadKey,
  email: String(lead.email || "").trim().toLowerCase(),
  tenant_id: tenantId,
  trace_id: traceId,
  tier: tier,
  score: score,
  channel: channel,
  chat_id: String(req.chat_id || "").trim(),
  max_words: maxWords,
  dry_run: dryRun,
  lead_block: leadBlock,
  evidence_block: evidenceBlock,
  ground_truth: groundTruth,
  sender_block: "Tejesh, n8n automation engineer. Writing because the lead came in through the site form.",
  draft_override: String(req.draft_override || ""),
  governance_action_type: String(req.governance_action_type || "send").trim().toLowerCase(),
  simulate_decision: String(req.simulate_decision || ""),
  source_workflow: String(req.source_workflow || "unknown"),
  request_digest: fnv(tenantId + "|" + leadKey + "|" + channel + "|" + tier),
  allowed: blockers.length === 0,
  blockers: blockers,
  started_at_ms: Date.now()
} }];

const req = $("Normalise Outreach Request").first().json;
return [{ json: {
  draft: req.draft_override,
  draft_source: "supplied",
  model_provider: null,
  model_latency_ms: 0,
  prompt_sha: null
} }];

const req = $("Normalise Outreach Request").first().json;
const incoming = $input.first().json;
const draft = String(incoming.draft || "").trim();

const BANNED = ["hope this email finds you well", "hope this finds you well", "i hope you are well", "quick question", "just circling back", "circling back", "touching base", "reaching out to see", "game-changing", "game changing", "revolutionary", "world-class", "best-in-class", "cutting-edge", "10x", "synergy", "low-hanging fruit", "no-brainer", "guarantee", "guaranteed", "skyrocket", "supercharge"];

const issues = [];
const warnings = [];

const words = draft.split(/\s+/).filter(function (w) { return w.length > 0; });
if (!draft) { issues.push({ rule: "empty_draft", detail: "the draft is empty" }); }
if (words.length > req.max_words) { issues.push({ rule: "too_long", detail: words.length + " words exceeds the " + req.max_words + "-word limit for " + req.channel }); }

if (/\{\{|\}\}|\[\[|\]\]|<[A-Z_]{3,}>|\bFIRST_?NAME\b|\bCOMPANY_?NAME\b/i.test(draft)) {
  issues.push({ rule: "placeholder_leak", detail: "an unfilled template placeholder survived into the draft" });
}

const lower = draft.toLowerCase();
BANNED.forEach(function (phrase) {
  if (lower.indexOf(phrase) !== -1) { issues.push({ rule: "banned_phrase", detail: "contains \"" + phrase + "\"" }); }
});

const withoutDurations = lower.replace(/\b(5|10|15|20|25|30|45|60|90)\s*(-|\s)?(min|mins|minute|minutes)\b/g, " ");
const figures = withoutDurations.match(/\b\d[\d,.]*\s?[%kmb]?\b/g) || [];
const ungrounded = [];
figures.forEach(function (f) {
  const needle = f.trim();
  if (needle.length < 1) { return; }
  if (req.ground_truth.indexOf(needle) === -1) { ungrounded.push(needle); }
});
if (ungrounded.length) {
  issues.push({ rule: "ungrounded_figure", detail: "figure(s) not present in the lead or the evidence: " + ungrounded.join(", ") });
}

if (/https?:\/\/|www\./i.test(draft)) { issues.push({ rule: "link_present", detail: "the draft contains a link; links are added by the sending channel, not the model" }); }

const exclamations = (draft.match(/!/g) || []).length;
if (exclamations > 1) { warnings.push({ rule: "exclamations", detail: exclamations + " exclamation marks" }); }
const shouty = (draft.match(/\b[A-Z]{4,}\b/g) || []).filter(function (w) { return w !== "ASAP"; });
if (shouty.length) { warnings.push({ rule: "shouting", detail: "all-caps word(s): " + shouty.join(", ") }); }
if (draft.indexOf("?") === -1) { warnings.push({ rule: "no_ask", detail: "the draft does not ask anything" }); }

const copyScore = Math.max(0, Math.min(1, 1 - (issues.length * 0.25) - (warnings.length * 0.1)));

function fnv(s) {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); }
  return (h >>> 0).toString(16).padStart(8, "0");
}

return [{ json: {
  draft: draft,
  draft_source: incoming.draft_source,
  model_provider: incoming.model_provider,
  model_latency_ms: incoming.model_latency_ms,
  prompt_sha: incoming.prompt_sha,
  word_count: words.length,
  copy_ok: issues.length === 0,
  copy_score: Math.round(copyScore * 100) / 100,
  copy_issues: issues,
  copy_warnings: warnings,
  message_digest: fnv(draft)
} }];

const raw = $input.first().json;
const res = (raw && raw.json) ? raw.json : raw;
let promptSha = null;
try { const p = $("Get Outreach Prompt (08)").first().json; promptSha = (p.json ? p.json.sha : p.sha) || null; } catch (e) { }
const text = String(res.output || "").trim().replace(/^["\u201c]|["\u201d]$/g, "").trim();
return [{ json: {
  draft: text,
  draft_source: "model",
  model_provider: res.selected_provider || null,
  model_latency_ms: Number(res.latency_ms || 0),
  prompt_sha: promptSha
} }];

const req = $("Normalise Outreach Request").first().json;

let decided = null;
try { decided = $("Decide Send Request").first().json; } catch (e) { }
let gov = null;
try { const g = $("Governance Gate (05)").first().json; gov = (g.json ? g.json : g); } catch (e) { }

let stage = "qualification";
let reasons = req.blockers || [];
if (gov && gov.approved === false) {
  stage = "governance";
  reasons = [String(gov.decision || "rejected") + " at risk level " + String(gov.risk_level || "unknown") + ": " + String(gov.decision_reason || "no reason given")];
} else if (decided && decided.ask_governance === false) {
  stage = "copy_and_verification";
  reasons = decided.blockers;
}

return [{ json: {
  sent: false,
  delivery_status: "blocked",
  delivery_detail: "blocked at the " + stage + " stage",
  blocked_stage: stage,
  channel: req.channel,
  blocked_reasons: reasons,
  governance_decision: gov ? (gov.decision || "rejected") : "not_requested",
  risk_level: gov ? (gov.risk_level || "unknown") : "not_assessed",
  decided_by: gov ? (gov.decided_by || "unknown") : "system",
  draft: decided ? decided.draft : "",
  message_digest: decided ? decided.message_digest : ""
} }];

const req = $("Normalise Outreach Request").first().json;
const copy = $("Check Copy Rules").first().json;
const raw = $input.first().json;
const v = (raw && raw.json) ? raw.json : raw;

const blockers = [];
copy.copy_issues.forEach(function (i) { blockers.push(i.rule + ": " + i.detail); });
if (v.verified === false) { blockers.push("verification: the draft was not verified against the evidence (" + ((v.issues || []).length) + " issue(s))"); }

return [{ json: {
  ask_governance: blockers.length === 0,
  blockers: blockers,
  draft: copy.draft,
  word_count: copy.word_count,
  copy_score: copy.copy_score,
  copy_issues: copy.copy_issues,
  copy_warnings: copy.copy_warnings,
  message_digest: copy.message_digest,
  draft_source: copy.draft_source,
  model_provider: copy.model_provider,
  prompt_sha: copy.prompt_sha,
  verified: v.verified === true,
  verification_score: v.score === undefined ? null : v.score,
  verification_issues: v.issues || [],
  verification_mode: v.mode || "unknown"
} }];

const req = $("Normalise Outreach Request").first().json;
const decided = $("Decide Send Request").first().json;
const raw = $input.first().json || {};
const messageId = (raw.result && raw.result.message_id) || raw.message_id || "";
const failed = !!raw.error || !messageId;
let gov = {};
try { const g = $("Governance Gate (05)").first().json; gov = (g.json ? g.json : g); } catch (e) { }
return [{ json: {
  sent: !failed,
  delivery_status: failed ? "send_failed" : "sent",
  delivery_detail: failed ? String((raw.error && (raw.error.message || raw.error)) || "the channel returned no message id") : ("telegram message " + messageId),
  channel: req.channel,
  blocked_reasons: [],
  governance_decision: gov.decision || "approved",
  risk_level: gov.risk_level || "unknown",
  decided_by: gov.decided_by || "unknown",
  draft: decided.draft,
  message_digest: decided.message_digest
} }];

const req = $("Normalise Outreach Request").first().json;
const decided = $("Decide Send Request").first().json;
let gov = {};
try { const g = $("Governance Gate (05)").first().json; gov = (g.json ? g.json : g); } catch (e) { }

const reason = req.dry_run
  ? "dry_run=true: the message was drafted, checked, verified and approved, but not sent"
  : "the " + req.channel + " channel has no sending credential configured in this instance";

return [{ json: {
  sent: false,
  delivery_status: req.dry_run ? "simulated" : "channel_not_configured",
  delivery_detail: reason,
  channel: req.channel,
  blocked_reasons: [],
  governance_decision: gov.decision || "approved",
  risk_level: gov.risk_level || "unknown",
  decided_by: gov.decided_by || "unknown",
  draft: decided.draft,
  message_digest: decided.message_digest
} }];

const req = $("Normalise Outreach Request").first().json;

const OUTCOMES = ["Capture Send", "Simulate Channel Send", "Capture Blocked Send"];
let outcome = null;
for (const name of OUTCOMES) {
  try {
    const items = $(name).all();
    if (items && items.length) { outcome = items[0].json; break; }
  } catch (e) { }
}
if (!outcome) {
  outcome = { sent: false, delivery_status: "no_branch_ran", delivery_detail: "no outcome node produced a result; this is a wiring bug", channel: req.channel, blocked_reasons: [], governance_decision: "unknown", risk_level: "unknown", decided_by: "unknown", draft: "", message_digest: "" };
}

let decided = {};
try { decided = $("Decide Send Request").first().json; } catch (e) { }

return [{ json: {
  lead_key: req.lead_key,
  email: req.email,
  tenant_id: req.tenant_id,
  trace_id: req.trace_id,
  tier: req.tier,
  channel: outcome.channel,
  sent: outcome.sent === true,
  delivery_status: outcome.delivery_status,
  delivery_detail: outcome.delivery_detail,
  blocked_stage: outcome.blocked_stage || null,
  blocked_reasons: outcome.blocked_reasons || [],
  draft: outcome.draft || "",
  word_count: decided.word_count === undefined ? 0 : decided.word_count,
  message_digest: outcome.message_digest || "",
  copy: {
    score: decided.copy_score === undefined ? null : decided.copy_score,
    issues: decided.copy_issues || [],
    warnings: decided.copy_warnings || []
  },
  verification: {
    verified: decided.verified === true,
    score: decided.verification_score === undefined ? null : decided.verification_score,
    mode: decided.verification_mode || "not_run",
    issues: decided.verification_issues || []
  },
  governance: {
    decision: outcome.governance_decision,
    risk_level: outcome.risk_level,
    decided_by: outcome.decided_by,
    action_type: req.governance_action_type
  },
  provenance: {
    draft_source: decided.draft_source || "none",
    model_provider: decided.model_provider || null,
    prompt_sha: decided.prompt_sha || null,
    source_workflow: req.source_workflow,
    execution_id: $execution.id
  },
  dry_run: req.dry_run,
  latency_ms: Date.now() - Number(req.started_at_ms)
} }];

// Nine fixtures supply the draft, so the copy rules and the gate are the only
// things under test. O10 drafts with the real model.
const LEAD = { email: "ada@analytical.io", first_name: "Ada", last_name: "Lovelace", job_title: "VP of Engineering", company_name: "Analytical Engines", message: "We have 30k set aside and need this live this month." };

function qual(o) {
  const base = {
    lead_key: "ada@analytical.io",
    tenant_id: "acme",
    tier: "HOT",
    score: 92,
    outreach_allowed: true,
    outreach_block_reason: "",
    signals: { evidence: [{ signal: "budget_signal", quote: "We have 30k set aside" }] }
  };
  return JSON.stringify(Object.assign(base, o));
}

const CLEAN = "Hi Ada, you mentioned 30k set aside and wanting this live this month. Worth 15 minutes this week to see whether the timeline is realistic?";

const fixtures = [
  { case_id: "O01", note: "a clean draft is approved and simulated, not sent", channel: "email", qualification: qual({}), draft: CLEAN, simulate: "approve", expect_status: "simulated", expect_stage: null, expect_decision: "approved", expect_risk: "HIGH", expect_rule: "" },
  { case_id: "O02", note: "a banned phrase never reaches a human", channel: "email", qualification: qual({}), draft: "Hi Ada, quick question: we guarantee results. Worth 15 minutes?", simulate: "approve", expect_status: "blocked", expect_stage: "copy_and_verification", expect_decision: "not_requested", expect_risk: "not_assessed", expect_rule: "banned_phrase" },
  { case_id: "O03", note: "a figure that is not in the evidence blocks the send", channel: "email", qualification: qual({}), draft: "Hi Ada, teams like yours cut onboarding time by 40% after switching. Worth 15 minutes?", simulate: "approve", expect_status: "blocked", expect_stage: "copy_and_verification", expect_decision: "not_requested", expect_risk: "not_assessed", expect_rule: "ungrounded_figure" },
  { case_id: "O04", note: "an unfilled placeholder blocks the send", channel: "email", qualification: qual({}), draft: "Hi {{first_name}}, saw your note about 30k. Worth 15 minutes?", simulate: "approve", expect_status: "blocked", expect_stage: "copy_and_verification", expect_decision: "not_requested", expect_risk: "not_assessed", expect_rule: "placeholder_leak" },
  { case_id: "O05", note: "an email-length draft is too long for sms", channel: "sms", qualification: qual({}), draft: CLEAN + " I can share how other operations teams sequenced the same rollout, and what they would do differently a second time around, if that is useful to you.", simulate: "approve", expect_status: "blocked", expect_stage: "copy_and_verification", expect_decision: "not_requested", expect_risk: "not_assessed", expect_rule: "too_long" },
  { case_id: "O06", note: "a lead qualification refused is never drafted for", channel: "email", qualification: qual({ outreach_allowed: false, outreach_block_reason: "score 36 is below the ICP outreach floor of 50" }), draft: CLEAN, simulate: "approve", expect_status: "blocked", expect_stage: "qualification", expect_decision: "not_requested", expect_risk: "not_assessed", expect_rule: "" },
  { case_id: "O07", note: "a human rejection stops a clean draft", channel: "email", qualification: qual({}), draft: CLEAN, simulate: "reject", expect_status: "blocked", expect_stage: "governance", expect_decision: "rejected", expect_risk: "HIGH", expect_rule: "" },
  { case_id: "O08", note: "telegram without a chat id is refused before drafting", channel: "telegram", qualification: qual({}), draft: CLEAN, simulate: "approve", expect_status: "blocked", expect_stage: "qualification", expect_decision: "not_requested", expect_risk: "not_assessed", expect_rule: "" },
  { case_id: "O09", note: "a destructive verb in the copy is escalated to CRITICAL and denied", channel: "email", qualification: qual({}), draft: "Hi Ada, happy to help you delete the manual steps you mentioned. Worth 15 minutes?", simulate: "approve", expect_status: "blocked", expect_stage: "governance", expect_decision: "denied", expect_risk: "CRITICAL", expect_rule: "" },
  { case_id: "O10", note: "live: the real model drafts, structure only is asserted", channel: "email", qualification: qual({}), draft: "", simulate: "approve", expect_status: null, expect_stage: null, expect_decision: null, expect_risk: null, expect_rule: "" }
];

return fixtures.map(function (f) {
  return { json: {
    case_id: f.case_id,
    note: f.note,
    lead: JSON.stringify(LEAD),
    qualification: f.qualification,
    channel: f.channel,
    dry_run: "true",
    draft_override: f.draft,
    governance_action_type: "send",
    simulate_decision: f.simulate,
    chat_id: "",
    tenant_id: "acme",
    trace_id: "trace-" + $execution.id + "-" + f.case_id,
    source_workflow: "13-test-suite",
    expect_status: f.expect_status,
    expect_stage: f.expect_stage,
    expect_decision: f.expect_decision,
    expect_risk: f.expect_risk,
    expect_rule: f.expect_rule
  } };
});

const rows = $input.all().map(function (i) { return i.json; });

const cases = rows.map(function (r) {
  const checks = [];
  if (r.expect_status === null) {
    checks.push({ name: "draft_written", pass: String(r.draft || "").length > 0, expected: "a non-empty draft", actual: String(r.draft || "").length + " chars" });
    checks.push({ name: "drafted_by_model", pass: r.draft_source === "model", expected: "model", actual: r.draft_source });
    checks.push({ name: "provider_recorded", pass: !!r.model_provider, expected: "a provider name", actual: r.model_provider });
    checks.push({ name: "never_sent_in_dry_run", pass: r.sent === false, expected: false, actual: r.sent });
    checks.push({ name: "within_word_limit", pass: typeof r.word_count === "number" && r.word_count > 0 && r.word_count <= 90, expected: "1..90 words", actual: r.word_count });
  } else {
    checks.push({ name: "delivery_status", pass: r.actual_status === r.expect_status, expected: r.expect_status, actual: r.actual_status });
    checks.push({ name: "blocked_stage", pass: (r.actual_stage || null) === r.expect_stage, expected: r.expect_stage, actual: r.actual_stage });
    checks.push({ name: "governance_decision", pass: r.actual_decision === r.expect_decision, expected: r.expect_decision, actual: r.actual_decision });
    checks.push({ name: "risk_level", pass: r.actual_risk === r.expect_risk, expected: r.expect_risk, actual: r.actual_risk });
    checks.push({ name: "never_sent_in_dry_run", pass: r.sent === false, expected: false, actual: r.sent });
    if (r.expect_rule) {
      checks.push({ name: "copy_rule_hit", pass: (r.copy_rules_hit || []).indexOf(r.expect_rule) !== -1, expected: r.expect_rule, actual: r.copy_rules_hit });
    }
  }
  // Correlation must survive every path, including the ones that produce no draft.
  checks.push({ name: "tenant_echoed", pass: r.tenant_id === "acme", expected: "acme", actual: r.tenant_id });
  checks.push({ name: "trace_echoed", pass: r.trace_id === r.expect_trace, expected: r.expect_trace, actual: r.trace_id });
  const failed = checks.filter(function (c) { return !c.pass; });
  return { case_id: r.case_id, note: r.note, passed: failed.length === 0, checks: checks, latency_ms: r.latency_ms };
});

const passed = cases.filter(function (c) { return c.passed; }).length;
return [{ json: {
  suite: "13-outreach-composer",
  run_at: new Date().toISOString(),
  execution_id: $execution.id,
  total: cases.length,
  passed: passed,
  failed: cases.length - passed,
  all_passed: passed === cases.length && cases.length === 10,
  cases: cases
} }];
